test:
assert_eq!(roman_to_int("III"), 3);
    assert_eq!(roman_to_int("IV"), 4);
    assert_eq!(roman_to_int("IX"), 9);
    assert_eq!(roman_to_int("LVIII"), 58);
    assert_eq!(roman_to_int("MCMXCIV"), 1994);
    assert_eq!(roman_to_int("XLII"), 42);
    assert_eq!(roman_to_int("CDXLIV"), 444);

assert_eq!(is_balanced("([]{})"), true);
    assert_eq!(is_balanced("([)]"), false);
    assert_eq!(is_balanced("((("), false);
    assert_eq!(is_balanced("a(b)c[d]{e}"), true);
    assert_eq!(is_balanced("}"), false);
    assert_eq!(is_balanced(""), true);
    assert_eq!(is_balanced("{[()()]}"), true);

assert_eq!(spiral_order(vec![vec![1,2,3],vec![4,5,6],vec![7,8,9]]), vec![1,2,3,6,9,8,7,4,5]);
    assert_eq!(spiral_order(vec![vec![1,2,3,4],vec![5,6,7,8],vec![9,10,11,12]]), vec![1,2,3,4,8,12,11,10,9,5,6,7]);
    assert_eq!(spiral_order(vec![vec![1]]), vec![1]);
    let empty: Vec<Vec<i32>> = vec![];
    assert_eq!(spiral_order(empty), Vec::<i32>::new());

let mut c = Lru::new(2);
    c.put(1,1); c.put(2,2);
    assert_eq!(c.get(1), Some(1));
    c.put(3,3); // evicts key 2
    assert_eq!(c.get(2), None);
    c.put(4,4); // evicts key 1
    assert_eq!(c.get(1), None);
    assert_eq!(c.get(3), Some(3));
    assert_eq!(c.get(4), Some(4));

assert_eq!(my_atoi("42"), 42);
    assert_eq!(my_atoi("   -42"), -42);
    assert_eq!(my_atoi("4193 with words"), 4193);
    assert_eq!(my_atoi("words and 987"), 0);
    assert_eq!(my_atoi("-91283472332"), i32::MIN);
    assert_eq!(my_atoi("2147483648"), i32::MAX);
    assert_eq!(my_atoi("+1"), 1);
    assert_eq!(my_atoi(""), 0);

let got = group_anagrams(vec!["eat".into(),"tea".into(),"tan".into(),"ate".into(),"nat".into(),"bat".into()]);
    assert_eq!(got.len(), 3);
    let mut sizes: Vec<usize> = got.iter().map(|g| g.len()).collect();
    sizes.sort();
    assert_eq!(sizes, vec![1usize,2,3]);
    for g in &got { let mut b: Vec<char> = g[0].chars().collect(); b.sort(); for w in g { let mut a: Vec<char> = w.chars().collect(); a.sort(); assert_eq!(a, b); } }
